// Every fixed UI string from the 01-UI-SPEC Copywriting Contract, in one place. Components import
// from here and write no copy inline. These are interface labels shown on screen, never spoken
// (Snow's spoken lines are generated by the model).

export const copy = {
  mute: "Mute microphone",
  unmute: "Unmute microphone",
  muted: "Muted",
  interrupted: "Interrupted",
  jumpToLatest: "Jump to latest",
  asleepChip: "Asleep",

  emptyStandingBy: {
    heading: 'Say "Hey Snow" to start',
    body: "Snow listens for the wake phrase on this PC. Nothing is sent anywhere until you wake it.",
  },
  emptyAsleep: { heading: "Snow is asleep", body: 'Say "Hey Snow" to wake it.' },
  emptyMuted: {
    heading: "Microphone is muted",
    body: "Snow cannot hear you. Click Unmute microphone to turn it back on.",
  },

  muteBanner: "Microphone is muted. Snow cannot hear you.",
  connectionBanner: {
    heading: "Cannot reach Snow's core",
    body: "Reconnecting automatically. Mute is unavailable until the connection returns.",
  },

  // The visually hidden role="status" region says only these five things.
  announce: {
    muted: "Microphone muted",
    unmuted: "Microphone unmuted",
    connectionLost: "Connection to Snow's core lost",
    reconnected: "Reconnected",
    subsystemDown: (names: string[]) => `${names.join(", ")} down`,
  },

  noModelReachable:
    "No language model is reachable, so Snow cannot reply. Open Language models below to see which providers failed.",
  privacyBlock:
    "Request held back: only providers not cleared for private data were available. Add a trusted provider key to continue.",
  switched: (role: string, provider: string, reason: string) =>
    `Switched ${role} model to ${provider} (${reason}).`,

  voiceOutOfCredits: "Cartesia credits are used up. Big moments use the everyday voice.",
  voiceUnreachable: "Cartesia is unreachable. Big moments use the everyday voice.",
  sttUnreachable: "Groq speech-to-text is unreachable. Using the local model.",
  sttLimit: (hhmm: string) =>
    `Groq speech-to-text limit reached. Using the local model until ${hhmm}.`,
  creditsUnavailable: "Unavailable",
  creditsUnavailableHelper: "Cartesia did not report a balance.",

  subsystemDown: "Down",
  subsystemRestartingHelper: "Snow is restarting it automatically.",
  subsystemFailedHelper: "Could not restart. See logs.",
  notConfigured: "Not configured",
  notConfiguredHelper: "No key stored. Run `snow setup` to add one.",
} as const;

// SwitchReason on the wire to the words the contract allows; the two configuration faults read as
// a service error to the user.
const SWITCH_REASONS: Record<string, string> = {
  rate_limit: "rate limit",
  out_of_quota: "out of quota",
  service_error: "service error",
  timeout: "timeout",
  unreachable: "unreachable",
  bad_key: "service error",
  config_error: "service error",
};

export const switchReasonText = (reason: string): string =>
  SWITCH_REASONS[reason] ?? "service error";

// The hub stores a system row's text as space-separated key=value facts (hub/projections.py); the
// store writes live rows in the same shape, so snapshot and live rows render identically.
function parseFacts(facts: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const part of facts.split(" ")) {
    const i = part.indexOf("=");
    if (i > 0) out[part.slice(0, i)] = part.slice(i + 1);
  }
  return out;
}

/** The sentence a system row shows. `label` turns a provider id into its display name. */
export function systemRowText(
  systemEvent: string | null | undefined,
  facts: string,
  label: (providerId: string) => string = (id) => id,
): string {
  if (systemEvent === "llm.exhausted") return copy.noModelReachable;
  if (systemEvent === "llm.blocked_privacy") return copy.privacyBlock;
  if (systemEvent === "llm.switch") {
    const f = parseFacts(facts);
    const to = f.to?.split("/")[0];
    if (f.role && to && f.reason) {
      return copy.switched(f.role, label(to), switchReasonText(f.reason));
    }
  }
  return facts;
}
